pub fn soma_um(fila: &mut Vec<i32>) {
    for x in fila {
        *x += 1;
    }
}

testsCode:
use desafio::soma_um;

#[test]
fn testa_o_soma_um_na_fila() {
    let mut fila = vec![1, 2, 3];
    soma_um(&mut fila);
    assert_eq!(fila[0], 2);
}

#[test]
fn testa_a_fila_inteira_mudou() {
    let mut fila = vec![9, 9];
    soma_um(&mut fila);
    assert_eq!(fila[0], 10);
    assert_eq!(fila[1], 10);
}
